package com.example.crm.task; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api/tasks") public class TaskController {final TaskService s; TaskController(TaskService x){s=x;} record Req(@NotBlank String title,LocalDate dueDate,UUID customerId,UUID dealId){} @GetMapping public ResponseEntity<List<TaskDto>> all(){return ResponseEntity.ok(s.all());} @GetMapping("/{id}") public ResponseEntity<TaskDto> one(@PathVariable UUID id){try{return ResponseEntity.ok(s.one(id));}catch(NoSuchElementException e){return ResponseEntity.notFound().build();}} @PostMapping @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public ResponseEntity<TaskDto> create(@Valid @RequestBody Req r){return ResponseEntity.status(201).body(s.create(r.title(),r.dueDate(),r.customerId(),r.dealId()));} @PutMapping("/{id}") @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public ResponseEntity<TaskDto> update(@PathVariable UUID id,@Valid @RequestBody Req r){try{return ResponseEntity.ok(s.update(id,r.title(),r.dueDate(),r.customerId(),r.dealId()));}catch(NoSuchElementException e){return ResponseEntity.notFound().build();}} @PatchMapping("/{id}/complete") @PreAuthorize("hasAnyRole('OPERATOR','ADMIN')") public ResponseEntity<TaskDto> complete(@PathVariable UUID id){try{return ResponseEntity.ok(s.complete(id));}catch(NoSuchElementException e){return ResponseEntity.notFound().build();}} @DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<Void> delete(@PathVariable UUID id){try{s.delete(id);return ResponseEntity.noContent().build();}catch(NoSuchElementException e){return ResponseEntity.notFound().build();}} }
